import{_ as e,o as a,c as i,ah as r}from"./chunks/framework.CPHJ30oF.js";const k=JSON.parse('{"title":"20-从传统物理机到Docker化改造的8个避坑指南","description":"","frontmatter":{},"headers":[{"level":2,"title":"引言","slug":"引言","link":"#引言","children":[]},{"level":2,"title":"1. 不要一上来就全量容器化","slug":"_1-不要一上来就全量容器化","link":"#_1-不要一上来就全量容器化","children":[]},{"level":2,"title":"2. 显式化依赖边界","slug":"_2-显式化依赖边界","link":"#_2-显式化依赖边界","children":[]},{"level":2,"title":"3. 不要把数据与容器绑得太死","slug":"_3-不要把数据与容器绑得太死","link":"#_3-不要把数据与容器绑得太死","children":[]},{"level":2,"title":"4. 规划网络与服务发现","slug":"_4-规划网络与服务发现","link":"#_4-规划网络与服务发现","children":[]},{"level":2,"title":"5. 配置不要写死在镜像里","slug":"_5-配置不要写死在镜像里","link":"#_5-配置不要写死在镜像里","children":[]},{"level":2,"title":"6. 逐步验证发布与回滚","slug":"_6-逐步验证发布与回滚","link":"#_6-逐步验证发布与回滚","children":[]},{"level":2,"title":"7. 关注安全与权限","slug":"_7-关注安全与权限","link":"#_7-关注安全与权限","children":[]},{"level":2,"title":"8. 不要忽视运维与监控","slug":"_8-不要忽视运维与监控","link":"#_8-不要忽视运维与监控","children":[]},{"level":2,"title":"总结","slug":"总结","link":"#总结","children":[]}],"relativePath":"docker/20-从传统物理机到Docker化改造的8个避坑指南.md","filePath":"docker/20-从传统物理机到Docker化改造的8个避坑指南.md"}'),_={name:"docker/20-从传统物理机到Docker化改造的8个避坑指南.md"};function t(n,l,h,c,o,d){return a(),i("div",null,[...l[0]||(l[0]=[r('<h1 id="_20-从传统物理机到docker化改造的8个避坑指南" tabindex="-1">20-从传统物理机到Docker化改造的8个避坑指南 <a class="header-anchor" href="#_20-从传统物理机到docker化改造的8个避坑指南" aria-label="Permalink to “20-从传统物理机到Docker化改造的8个避坑指南”">​</a></h1><h2 id="引言" tabindex="-1">引言 <a class="header-anchor" href="#引言" aria-label="Permalink to “引言”">​</a></h2><p>传统应用迁移到 Docker 并不是“只要装进容器就行”。它需要避免依赖遗漏、网络混乱、数据丢失、配置不清和发布失控等陷阱。</p><p>本篇文章总结 8 个常见避坑点，帮助你把 Docker 化改造做成可控、可复现的工程实践。</p><h2 id="_1-不要一上来就全量容器化" tabindex="-1">1. 不要一上来就全量容器化 <a class="header-anchor" href="#_1-不要一上来就全量容器化" aria-label="Permalink to “1. 不要一上来就全量容器化”">​</a></h2><p>大体量、强耦合的传统系统一次性容器化风险很大。建议：</p><ul><li>从最小可独立部署的服务开始；</li><li>先迁移辅助服务或新模块；</li><li>逐步推进到核心业务。</li></ul><h2 id="_2-显式化依赖边界" tabindex="-1">2. 显式化依赖边界 <a class="header-anchor" href="#_2-显式化依赖边界" aria-label="Permalink to “2. 显式化依赖边界”">​</a></h2><p>传统应用经常依赖宿主机工具、系统库、配置文件或运维脚本。迁移前必须梳理这些依赖，并在 Dockerfile 中显式安装或挂载。</p><h2 id="_3-不要把数据与容器绑得太死" tabindex="-1">3. 不要把数据与容器绑得太死 <a class="header-anchor" href="#_3-不要把数据与容器绑得太死" aria-label="Permalink to “3. 不要把数据与容器绑得太死”">​</a></h2><p>容器是短生命周期实体，持久化数据应放到数据卷或外部存储。否则容器重建就会导致数据丢失。</p><h2 id="_4-规划网络与服务发现" tabindex="-1">4. 规划网络与服务发现 <a class="header-anchor" href="#_4-规划网络与服务发现" aria-label="Permalink to “4. 规划网络与服务发现”">​</a></h2><p>容器化后服务 IP 可能频繁变化。提前规划：</p><ul><li>网络模式；</li><li>端口映射；</li><li>服务发现机制；</li><li>域名或负载均衡配置。</li></ul><h2 id="_5-配置不要写死在镜像里" tabindex="-1">5. 配置不要写死在镜像里 <a class="header-anchor" href="#_5-配置不要写死在镜像里" aria-label="Permalink to “5. 配置不要写死在镜像里”">​</a></h2><p>镜像应保持通用，环境差异通过运行时注入：</p><ul><li>环境变量；</li><li>配置文件挂载；</li><li>配置中心。</li></ul><h2 id="_6-逐步验证发布与回滚" tabindex="-1">6. 逐步验证发布与回滚 <a class="header-anchor" href="#_6-逐步验证发布与回滚" aria-label="Permalink to “6. 逐步验证发布与回滚”">​</a></h2><p>迁移过程中，先做小范围试点：</p><ul><li>验证构建流程；</li><li>验证监控与告警；</li><li>验证回滚机制；</li><li>再逐步扩大规模。</li></ul><h2 id="_7-关注安全与权限" tabindex="-1">7. 关注安全与权限 <a class="header-anchor" href="#_7-关注安全与权限" aria-label="Permalink to “7. 关注安全与权限”">​</a></h2><p>容器迁移后不要默认使用 root。建议：</p><ul><li>使用非 root 用户；</li><li>限制网络和文件权限；</li><li>扫描镜像漏洞；</li><li>保护敏感凭证。</li></ul><h2 id="_8-不要忽视运维与监控" tabindex="-1">8. 不要忽视运维与监控 <a class="header-anchor" href="#_8-不要忽视运维与监控" aria-label="Permalink to “8. 不要忽视运维与监控”">​</a></h2><p>容器化不是交付的终点，而是运行平台的起点。</p><ul><li>监控容器资源与服务健康；</li><li>日志集中收集；</li><li>管理镜像版本；</li><li>定期更新基础镜像。</li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to “总结”">​</a></h2><p>从传统物理机迁移到 Docker，需要更强的“工程化思维”。避开全盘容器化、隐式依赖、数据绑定、硬编码配置和发布盲点，才能让迁移过程更稳妥。Docker 化改造成功的关键，不是“跑起来”，而是“能持续、可控、可回滚地运行”。</p>',28)])])}const p=e(_,[["render",t]]);export{k as __pageData,p as default};
